# rcpp von Bertalanffy growth ----
## Setup ----
make_vonb_schnute_test_context <- function() {
  data("data_big", package = "FIMS")
  fims_frame <- FIMS::FIMSFrame(data_big)

  ages <- FIMS::get_ages(fims_frame)
  if (length(ages) == 0 || all(is.na(ages))) {
    reference_age_for_length_young <- 0
    reference_age_for_length_old <- FIMS::get_n_ages(fims_frame) - 1
  } else {
    reference_age_for_length_young <- min(ages, na.rm = TRUE)
    reference_age_for_length_old <- max(ages, na.rm = TRUE)
  }

  list(
    fims_frame = fims_frame,
    reference_age_for_length_young = reference_age_for_length_young,
    reference_age_for_length_old = reference_age_for_length_old,
    mean_length_young = 275,
    mean_length_old = 725,
    growth_coefficient = 0.18,
    length_weight_a = 2.5e-11,
    length_weight_b = 3,
    length_at_age_sd_young = 28,
    length_at_age_sd_old = 73
  )
}

ad_fabs <- function(x, C = 1e-5) sqrt(x * x + C)
ad_max <- function(a, b, C = 1e-5) 0.5 * (a + b + ad_fabs(a - b, C))

new_vonb_schnute <- function(
  ctx,
  mean_length_young_in = ctx$mean_length_young,
  mean_length_old_in = ctx$mean_length_old,
  growth_coefficient_in = ctx$growth_coefficient,
  reference_age_for_length_young_in = ctx$reference_age_for_length_young,
  reference_age_for_length_old_in = ctx$reference_age_for_length_old,
  length_weight_a_in = ctx$length_weight_a,
  length_weight_b_in = ctx$length_weight_b,
  length_at_age_sd_young_in = ctx$length_at_age_sd_young,
  length_at_age_sd_old_in = ctx$length_at_age_sd_old
) {
  vb <- methods::new(FIMS::VonBertalanffySchnuteGrowth)

  vb$mean_length_young$resize(1)
  vb$mean_length_young[1]$value <- mean_length_young_in

  vb$mean_length_old$resize(1)
  vb$mean_length_old[1]$value <- mean_length_old_in

  vb$growth_coefficient$resize(1)
  vb$growth_coefficient[1]$value <- growth_coefficient_in

  vb$reference_age_for_length_young$resize(1)
  vb$reference_age_for_length_young[1]$value <- reference_age_for_length_young_in

  vb$reference_age_for_length_old$resize(1)
  vb$reference_age_for_length_old[1]$value <- reference_age_for_length_old_in

  vb$length_weight_a$resize(1)
  vb$length_weight_a[1]$value <- length_weight_a_in

  vb$length_weight_b$resize(1)
  vb$length_weight_b[1]$value <- length_weight_b_in

  vb$length_at_age_sd_young$resize(1)
  vb$length_at_age_sd_young[1]$value <- length_at_age_sd_young_in

  vb$length_at_age_sd_old$resize(1)
  vb$length_at_age_sd_old[1]$value <- length_at_age_sd_old_in

  vb$n_ages$set(FIMS::get_n_ages(ctx$fims_frame))

  vb
}

make_vonb_traditional_test_context <- function() {
  list(
    asymptotic_length = 100,
    growth_coefficient = 0.2,
    age_at_zero_length = -0.5,
    length_weight_a = 1e-5,
    length_weight_b = 3,
    log_sd_asymptotic_length = log(0.1),
    log_sd_growth_coefficient = log(0.1),
    asymptotic_length_growth_coefficient_logit_corr = 0
  )
}

new_vonb_traditional <- function(
  ctx,
  include_delta_method_variability = TRUE
) {
  vb <- methods::new(FIMS::VonBertalanffyTraditionalGrowth)

  vb$asymptotic_length$resize(1)
  vb$asymptotic_length[1]$value <- ctx$asymptotic_length

  vb$growth_coefficient$resize(1)
  vb$growth_coefficient[1]$value <- ctx$growth_coefficient

  vb$age_at_zero_length$resize(1)
  vb$age_at_zero_length[1]$value <- ctx$age_at_zero_length
  vb$age_at_zero_length[1]$estimation_type$set("constant")

  vb$length_weight_a$resize(1)
  vb$length_weight_a[1]$value <- ctx$length_weight_a

  vb$length_weight_b$resize(1)
  vb$length_weight_b[1]$value <- ctx$length_weight_b

  if (include_delta_method_variability) {
    vb$log_sd_asymptotic_length$resize(1)
    vb$log_sd_asymptotic_length[1]$value <- ctx$log_sd_asymptotic_length

    vb$log_sd_growth_coefficient$resize(1)
    vb$log_sd_growth_coefficient[1]$value <- ctx$log_sd_growth_coefficient

    vb$asymptotic_length_growth_coefficient_logit_corr$resize(1)
    vb$asymptotic_length_growth_coefficient_logit_corr[1]$value <-
      ctx$asymptotic_length_growth_coefficient_logit_corr
  }

  vb
}

## IO correctness ----
test_that("rcpp von Bertalanffy Schnute growth evaluate() works with correct input", {
  ctx <- make_vonb_schnute_test_context()
  vb <- new_vonb_schnute(ctx)
  on.exit(
    {
      rm(vb, ctx)
      gc()
    },
    add = TRUE
  )

  age <- ctx$reference_age_for_length_old
  denom_raw <- 1 - exp(-ctx$growth_coefficient *
    (ctx$reference_age_for_length_old - ctx$reference_age_for_length_young))
  denom <- ad_max(ad_fabs(denom_raw), 1e-8)

  expected_length_at_age <- ctx$mean_length_young +
    (ctx$mean_length_old - ctx$mean_length_young) *
      (1 - exp(-ctx$growth_coefficient * (age - ctx$reference_age_for_length_young))) / denom

  expected_weight_at_age <- ctx$length_weight_a * expected_length_at_age^ctx$length_weight_b

  #' @description Test that VonBertalanffySchnuteGrowth evaluate() returns expected
  #' weight-at-age under guarded denominator math.
  expect_equal(
    object = vb$evaluate(age),
    expected = expected_weight_at_age,
    tolerance = 1e-8
  )
})

test_that("rcpp von Bertalanffy Traditional growth evaluate() works with correct input", {
  ctx <- make_vonb_traditional_test_context()
  vb <- new_vonb_traditional(ctx)
  on.exit(
    {
      rm(vb, ctx)
      gc()
    },
    add = TRUE
  )

  age <- 5
  expected_length_at_age <- ctx$asymptotic_length *
    (1 - exp(-ctx$growth_coefficient * (age - ctx$age_at_zero_length)))
  expected_weight_at_age <- ctx$length_weight_a *
    expected_length_at_age^ctx$length_weight_b

  #' @description Test that VonBertalanffyTraditionalGrowth evaluate() returns
  #' expected weight-at-age from the Linf, K, t0 mean growth curve.
  expect_equal(
    object = vb$evaluate(age),
    expected = expected_weight_at_age,
    tolerance = 1e-8
  )
})

