test_that("estimated younger length loads below constant older length", {
  FIMS::clear()
  on.exit(FIMS::clear(), add = TRUE)

  ctx <- make_vonb_schnute_test_context()

  for (estimation_type in c("fixed_effects", "random_effects")) {
    FIMS::clear()

    vb <- new_vonb_schnute(ctx)
    vb$mean_length_young[1]$estimation_type$set(estimation_type)
    vb$mean_length_old[1]$estimation_type$set("constant")

    FIMS::CreateTMBModel()

    if (estimation_type == "fixed_effects") {
      working <- FIMS::get_fixed()
      other <- FIMS::get_random()
    } else {
      working <- FIMS::get_random()
      other <- FIMS::get_fixed()
    }

    #' @description The younger length is registered in the requested parameter category.
    expect_length(working, 1L)
    expect_length(other, 0L)

    #' @description The loader encodes estimated younger length on the bounded-logit scale.
    expect_equal(
      as.numeric(working),
      qlogis(ctx$mean_length_young / ctx$mean_length_old),
      tolerance = 1e-10
    )
  }
})

test_that("rcpp von Bertalanffy Traditional growth rejects non-finite t0", {
  ctx <- make_vonb_traditional_test_context()
  vb <- new_vonb_traditional(ctx)

  on.exit(
    {
      rm(vb, ctx)
      gc()
      FIMS::clear()
    },
    add = TRUE
  )

  #' @description Test that Traditional growth rejects non-finite t0 inputs
  #' during direct evaluation and registration for model use.
  for (invalid_t0 in c(NA_real_, NaN, Inf, -Inf)) {
    vb$age_at_zero_length[1]$value <- invalid_t0

    expect_error(
      vb$evaluate(5),
      regexp = "Initial age_at_zero_length \\(t0\\) is .*Supply a finite numeric value\\."
    )
    expect_error(
      vb$add_to_fims_tmb(),
      regexp = "Initial age_at_zero_length \\(t0\\) is .*Supply a finite numeric value\\."
    )
  }
})

## Error handling ----
test_that("rcpp von bertalanffy growth rejects nonfinite inputs", {
  FIMS::clear()
  on.exit(FIMS::clear(), add = TRUE)

  ctx <- make_vonb_schnute_test_context()
  fields <- c(
    "mean_length_young",
    "mean_length_old",
    "growth_coefficient",
    "reference_age_for_length_young",
    "reference_age_for_length_old",
    "length_weight_a",
    "length_weight_b",
    "length_at_age_sd_young",
    "length_at_age_sd_old"
  )

  for (field in fields) {
    for (value in c(NA_real_, NaN, Inf, -Inf)) {
      FIMS::clear()
      vb <- new_vonb_schnute(ctx)
      vb[[field]][1]$value <- value
      case <- paste(field, "=", value)

      #' @description Nonfinite Growth inputs are rejected by direct evaluation with a parameter-specific error.
      expect_error(
        vb$evaluate(ctx$reference_age_for_length_young),
        regexp = paste(field, "must be finite"),
        info = case
      )

      #' @description Nonfinite Growth inputs are rejected before loading the backend model.
      expect_error(
        FIMS::CreateTMBModel(),
        regexp = paste(field, "must be finite"),
        info = case
      )
    }
  }
})

test_that("rcpp Traditional growth rejects non-finite positive inputs", {
  ctx <- make_vonb_traditional_test_context()
  vb <- new_vonb_traditional(ctx)

  on.exit(
    {
      rm(vb, ctx)
      gc()
      FIMS::clear()
    },
    add = TRUE
  )

  fields <- c(
    "asymptotic_length",
    "growth_coefficient",
    "length_weight_a",
    "length_weight_b"
  )

  #' @description Test that positive Traditional growth inputs must also
  #' be finite during direct evaluation and registration.
  for (field in fields) {
    for (i in seq_along(ctx[[field]])) {
      original_value <- vb[[field]][i]$value

      for (invalid_value in c(NA_real_, NaN, Inf, -Inf)) {
        vb[[field]][i]$value <- invalid_value

        expected_message <- paste0(field, " must be finite")

        expect_error(
          vb$evaluate(5),
          regexp = expected_message
        )
        expect_error(
          vb$add_to_fims_tmb(),
          regexp = expected_message
        )
      }

      vb[[field]][i]$value <- original_value
    }
  }
})

test_that("rcpp von Bertalanffy Traditional delta variability requires constant t0", {
  ctx <- make_vonb_traditional_test_context()
